  void pickaxe()throws Exception{var at=plot;for(int x=0;x<5;x++)level.setBlock(at.offset(x,0,0),Blocks.DIAMOND_ORE.defaultBlockState(),18);assertToolClaims(at);MasterToolService.survey(guest);long cooldown=guest.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG).getLong("KingdomMasterSurveyNext");h.assertTrue(cooldown>level.getGameTime(),"Native ore survey commits a real cooldown");MasterToolService.survey(guest);h.assertTrue(guest.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG).getLong("KingdomMasterSurveyNext")==cooldown,"Immediate survey replay cannot extend or bypass cooldown");h.assertTrue(guest.getMainHandItem().get(DataComponents.UNBREAKABLE)!=null,"Purchased pickaxe is unbreakable");h.assertTrue(guest.gameMode.destroyBlock(at),"Actual eligible native first ore removal");phase=3;deadline=h.getTick()+40;}
  void axe(){var at=plot;treeAt=at;sapling=Items.OAK_SAPLING;guest.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.OAK_SAPLING));guest.gameMode.useItemOn(guest,level,guest.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(at.below().getCenter(),Direction.UP,at.below(),false));guest.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BONE_MEAL,64));for(int n=0;n<64&&level.getBlockState(at).getBlock() instanceof SaplingBlock;n++)guest.gameMode.useItemOn(guest,level,guest.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(at.getCenter(),Direction.UP,at,false));h.assertTrue(level.getBlockState(at).is(net.minecraft.tags.BlockTags.LOGS),"Actual native mature planted tree");TreeLifecycle.drain(guest.server,128);guest.setItemInHand(InteractionHand.MAIN_HAND,received);guest.getInventory().setItem(1,new ItemStack(Items.OAK_SAPLING,4));phase=4;deadline=h.getTick()+4;}
  void finish()throws Exception{if(gear==MasterGear.PICKAXE){for(int x=0;x<5;x++)h.assertTrue(level.getBlockState(plot.offset(x,0,0)).isAir(),"Bounded vein uses native successful removals");int diamonds=guest.getInventory().countItem(Items.DIAMOND)+level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(Vec3.atLowerCornerOf(plot.offset(-1,-1,-1)),Vec3.atLowerCornerOf(plot.offset(8,5,5)))).stream().filter(e->e.getItem().is(Items.DIAMOND)).mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(diamonds>=5&&diamonds<=35,"Native FortuneVI loot is conserved across normal pickup/world entities; no duplicate drops");h.assertTrue(!guest.getMainHandItem().isDamaged(),"Unbreakable pickaxe retains durability");}if(gear==MasterGear.AXE){for(var cell:nativeTreeCells)if(!cell.equals(treeAt))h.assertTrue(level.getBlockState(cell).isAir(),"Every exact authenticated native trunk cell was successfully removed");h.assertTrue(level.getBlockState(treeAt).getBlock().asItem()==sapling,"Whole actual native tree chopped and seed-funded replant succeeds; root="+level.getBlockState(treeAt)+" remainingLogs="+java.util.stream.StreamSupport.stream(BlockPos.betweenClosed(treeAt.offset(-6,0,-6),treeAt.offset(6,24,6)).spliterator(),false).filter(pos->level.getBlockState(pos).is(net.minecraft.tags.BlockTags.LOGS)).count()+" seeds="+guest.getInventory().countItem(sapling));if(!modTree){modTree=true;treeAt=plot.offset(7,0,0);var blocks=net.minecraft.core.registries.BuiltInRegistries.BLOCK;var items=net.minecraft.core.registries.BuiltInRegistries.ITEM;sapling=items.getOptional(net.minecraft.resources.ResourceLocation.parse("aether:skyroot_sapling")).orElseThrow();level.setBlock(treeAt.below(),blocks.getOptional(net.minecraft.resources.ResourceLocation.parse("aether:aether_dirt")).orElseThrow().defaultBlockState(),18);guest.moveTo(treeAt.getX()+2.5,treeAt.getY()+1,treeAt.getZ()+2.5);guest.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(sapling));guest.gameMode.useItemOn(guest,level,guest.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(treeAt.below().getCenter(),Direction.UP,treeAt.below(),false));guest.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BONE_MEAL,64));for(int i=0;i<64&&level.getBlockState(treeAt).getBlock() instanceof SaplingBlock;i++)guest.gameMode.useItemOn(guest,level,guest.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(treeAt.getCenter(),Direction.UP,treeAt,false));h.assertTrue(level.getBlockState(treeAt).is(net.minecraft.tags.BlockTags.LOGS),"Actual registered Aether Skyroot native growth");guest.setItemInHand(InteractionHand.MAIN_HAND,received);guest.getInventory().setItem(1,new ItemStack(sapling,4));phase=4;deadline=h.getTick()+4;return;}saved.putBoolean("modTree",true);}CommerceService.checkpoint(p);CommerceService.checkpoint(guest);saved.putLong("revision",store.revision());saved.putInt("guestXP",guest.experienceLevel);if(gear==MasterGear.WAND)prepareWandCrash();AtomicNbt.write(proof,saved);phase=0;com.mojang.logging.LogUtils.getLogger().info("MASTER_REWARD_NATIVE_PASSED: role={} actual saved24/4800Master/local purchase/exact price/private claim/replay/legitimate native pickup by non-Master/real signature use/materials-XP/native receipt; raw vanilla supplies/XP and terrain are explicit QA inputs; no profession XP/quest/rank/source evidence injection",role.id());h.succeed();}
  void prepareWandCrash()throws Exception{
   var before=MasterWorkTransaction.inventory(guest);var after=new ArrayList<>(before.stream().map(ItemStack::copy).toList());after=new ArrayList<>(FarmerInventoryExchange.plan(after,Map.of(Items.COBBLESTONE,3),Map.of()));var data=new CompoundTag();var original=new ListTag();var changed=new ListTag();for(int i=0;i<36;i++){original.add(before.get(i).saveOptional(guest.registryAccess()));changed.add(after.get(i).saveOptional(guest.registryAccess()));}data.put("before",original);data.put("after",changed);data.putInt("xp",0);var xp=new CompoundTag();xp.putInt("before",guest.experienceLevel);xp.putInt("after",guest.experienceLevel);xp.putInt("total",guest.totalExperience);xp.putFloat("progress",guest.experienceProgress);data.put("xpState",xp);data.putString("dimension",level.dimension().location().toString());var rows=new ListTag();for(int x=0;x<3;x++){var at=plot.offset(x,0,2);h.assertTrue(level.getBlockState(at).isAir(),"Actual fault site starts empty");var row=new CompoundTag();row.putLong("position",at.asLong());row.put("before",NbtUtils.writeBlockState(level.getBlockState(at)));row.put("after",NbtUtils.writeBlockState(Blocks.COBBLESTONE.defaultBlockState()));rows.add(row);}data.put("world",rows);CommerceService.checkpoint(guest);store.prepareMasterWork(UUID.randomUUID(),guest.getUUID(),MasterGear.WAND.id(),data);MasterWorldWork.apply(guest,rows);h.assertTrue(store.pendingItem().isPresent()&&guest.getInventory().countItem(Items.COBBLESTONE)==6,"Actual prepared world checkpoint saved BEFORE inventory debit; deliberate normal-stop interruption");saved.putBoolean("worldBeforePlayerInterruption",true);
  }
  void restore()throws Exception{saved=AtomicNbt.read(proof);h.assertTrue(saved.getUUID("buyer").equals(p.getUUID())&&store.balance(p.getUUID())==saved.getLong("balance")&&store.equipmentPurchases(p.getUUID(),gear.id())==saved.getInt("count")&&store.revision()==saved.getLong("revision"),"Exact purchase count/purse/Native operation restores once");CommerceService.verifyReceipt(p);CommerceService.verifyReceipt(guest);if(saved.getBoolean("worldBeforePlayerInterruption")){h.assertTrue(store.pendingItem().isEmpty()&&guest.getInventory().countItem(Items.COBBLESTONE)==6,"World-before-player interruption aborts once without consuming or duplicating materials");for(int x=0;x<3;x++)h.assertTrue(level.getBlockState(plot.offset(x,0,2)).isAir(),"Matching pending world placements roll back on actual process restart");}if(gear==MasterGear.CODEX||gear==MasterGear.EXTRACTION){h.assertTrue(level.getBlockState(plot).is(gear==MasterGear.CODEX?MasterGearItems.CODEX.get():MasterGearItems.EXTRACTION.get()),"Original purchased workstation survives restart");h.assertTrue(guest.getInventory().getItem(0).is(saved.contains("modEnchantment")?Items.DIAMOND_HELMET:Items.DIAMOND_SWORD)&&guest.getInventory().getItem(0).getDamageValue()==(saved.contains("modEnchantment")?23:70),"Exact modified equipment survives restart");}if(gear==MasterGear.WAND)for(int x=0;x<3;x++)h.assertTrue(level.getBlockState(plot.offset(x,0,0)).is(Blocks.COBBLESTONE),"Actual Wand world target blocks survive process restart");if(saved.getBoolean("wandModes")){for(var cell:BlockPos.betweenClosed(plot.offset(0,0,4),plot.offset(2,2,4)))h.assertTrue(level.getBlockState(cell).is(cell.getY()==plot.getY()?Blocks.DIORITE:Blocks.STONE),"Actual paid wall/replacement geometry restores");for(var cell:BlockPos.betweenClosed(plot.offset(0,0,7),plot.offset(1,0,8)))h.assertTrue(level.getBlockState(cell).is(Blocks.STONE),"Actual paid floor restores");}h.assertTrue(gear==MasterGear.PICKAXE?guest.experienceLevel>=saved.getInt("guestXP"):guest.experienceLevel==saved.getInt("guestXP"),"Native XP debit or legitimate mined experience restored");phase=0;com.mojang.logging.LogUtils.getLogger().info("MASTER_REWARD_RESTART_PASSED: role={} exact purse/count/rank/original resident/guest native receipt and XP persist",role.id());h.succeed();}
